/*
 * A366381  Lexicographically earliest infinite sequence such that a(i) = a(j)
 *          => A336466(i) = A336466(j) and A336467(i) = A336467(j) for all i,
 *          j >= 1, where A336466 is fully multiplicative with a(p) =
 *          oddpart(p-1) for any prime p and A336467 is fully multiplicative
 *          with a(2) = 1 and a(p) = oddpart(p+1) for...
 * https://oeis.org/A366381
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) is the lexicographically earliest sequence generated by
 *            assigning to each pair (A336466(n),A336467(n)) the smallest
 *            unused integer so that equal pairs get equal terms
 * Range:     u8 n <= 97, u16 n <= 9934, u32 n <= 9934, u64 n <= 9934,
 *            u128 n <= 9934, big any n
 * Helpers:   factor_u64, odd_part
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <stddef.h>
#include "../utils/factor_u64.h"   /* factor_u64 */
#include "../utils/odd_part.h"    /* odd_part */

/* Structure to hold the pair of multiplicative values for each index. */
struct Pair {
    seq_t x;  /* A336466(n) */
    seq_t y;  /* A336467(n) */
};

/* Cached data for the sequence. */
static size_t       cache_size  = 0;   /* allocated capacity */
static size_t       max_computed = 0;  /* highest n computed so far */
static seq_t       *a_cache     = NULL; /* a(i) values (labels) */
static struct Pair *pairs       = NULL; /* pairs for each index   */
static int          next_label  = 0;    /* label for the next new pair */

/* Ensure that the buffers can hold at least `need` elements. */
static void ensure_capacity(size_t need)
{
    if (need <= cache_size)
        return;
    size_t new_cap = cache_size ? cache_size * 2 : 64;
    while (new_cap < need)
        new_cap *= 2;
    a_cache = (seq_t*)realloc(a_cache, new_cap * sizeof(seq_t));
    pairs   = (struct Pair*)realloc(pairs, new_cap * sizeof(struct Pair));
    cache_size = new_cap;
}

/* Fast exponentiation for a seq_t base and a 64‑bit exponent. */
static seq_t seq_pow_uint(seq_t base, uint64_t exp)
{
    seq_t result = 1;
    while (exp) {
        if (exp & 1)
            result = result * base;
        base = base * base;
        exp >>= 1;
    }
    return result;
}

/* A336466(n): fully multiplicative, a(p) = oddpart(p-1). */
static seq_t compute_f1(uint64_t n)
{
    if (n <= 1)
        return 1;
    size_t cnt = 0;
    uint64_t primes[64];
    uint64_t exps[64];
    factor_u64(n, primes, exps, &cnt);
    seq_t res = 1;
    for (size_t i = 0; i < cnt; ++i) {
        uint64_t p = primes[i];
        uint64_t e = exps[i];
        seq_t odd = odd_part((seq_t)(p - 1));
        seq_t term = seq_pow_uint(odd, e);
        res = res * term;
    }
    return res;
}

/* A336467(n): fully multiplicative, a(2)=1, a(p)=oddpart(p+1) for odd primes p. */
static seq_t compute_f2(uint64_t n)
{
    if (n <= 1)
        return 1;
    size_t cnt = 0;
    uint64_t primes[64];
    uint64_t exps[64];
    factor_u64(n, primes, exps, &cnt);
    seq_t res = 1;
    for (size_t i = 0; i < cnt; ++i) {
        uint64_t p = primes[i];
        uint64_t e = exps[i];
        if (p == 2)            /* a(2) = 1, ignore the factor */
            continue;
        seq_t odd = odd_part((seq_t)(p + 1));
        seq_t term = seq_pow_uint(odd, e);
        res = res * term;
    }
    return res;
}

/* Public sequence function. */
seq_t a(idx_t n)
{
    if (n == 0)
        return 0;   /* undefined for n < 1; safety guard */

    /* Compute all values up to the requested n. */
    if ((size_t)n > max_computed) {
        size_t need = (size_t)n;
        ensure_capacity(need);
        for (size_t i = max_computed; i < need; ++i) {
            uint64_t idx = (uint64_t)(i + 1);        /* current index (1‑based) */
            seq_t f1 = compute_f1(idx);
            seq_t f2 = compute_f2(idx);

            int label = -1;
            /* Look for a previously seen pair. */
            for (size_t j = 0; j < i; ++j) {
                if (pairs[j].x == f1 && pairs[j].y == f2) {
                    label = (int)a_cache[j];
                    break;
                }
            }

            if (label == -1) {          /* new pair */
                ++next_label;
                label = next_label;
            }

            a_cache[i] = (seq_t)label;
            pairs[i].x = f1;
            pairs[i].y = f2;
        }
        max_computed = need;
    }
    return a_cache[n - 1];
}
